import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse(`{"title":"regex Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"regex","tag":"regex","title":"regex Tag","prev":null,"next":null,"posts":[{"title":"正则表达式匹配信用卡","url":"/posts/2023-07-09-credit-regex/","date":"2023-07-09 13:41","tags":["regex"],"html":"<p>最近在做支付相关的服务，需要检测用户输入的信用卡号是否合法，并且根据信用卡号规则显示对应的信用卡类型。这里记录一下如何使用正则表达式来匹配信用卡号。顺便说一下只有 AE 卡号的 CVV 是 4 位的，其他的都是 3 位。</p>\\n<h2 id=\\"银联卡\\" tabindex=\\"-1\\">银联卡 <a class=\\"header-anchor\\" href=\\"#银联卡\\" aria-label=\\"Permalink to &quot;银联卡&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>银联卡以 62 开头，借记卡是 19 位，信用卡是 14 位。一般支付的时候都是使用信用卡，所以我们只需要匹配 14 位的卡号。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^62</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{14}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"visa\\" tabindex=\\"-1\\">Visa <a class=\\"header-anchor\\" href=\\"#visa\\" aria-label=\\"Permalink to &quot;Visa&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Visa 信用卡以 4 开头，新卡长度为 16 位，旧卡长度为 13 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^4[0-9]{12}(?:[0-9]{3})?'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"mastercard\\" tabindex=\\"-1\\">MasterCard <a class=\\"header-anchor\\" href=\\"#mastercard\\" aria-label=\\"Permalink to &quot;MasterCard&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>MasterCard 信用卡以 51 到 55 开头或者是以 2221–2720 开头，长度为 16 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^(5[1-5]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{0,2}|22[2-9]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{1}|2[3-7]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{2})</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{12}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"amex\\" tabindex=\\"-1\\">Amex <a class=\\"header-anchor\\" href=\\"#amex\\" aria-label=\\"Permalink to &quot;Amex&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Amex 信用卡以 34 或者 37 开头，长度为 15 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^3[47]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{13}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"jcb\\" tabindex=\\"-1\\">Jcb <a class=\\"header-anchor\\" href=\\"#jcb\\" aria-label=\\"Permalink to &quot;Jcb&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Jcb 信用卡以 35 开头，长度为 16 位。以 2131 或者 1800 开头，长度为 15 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^(?:2131|1800|35</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{3})</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{11}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"diners\\" tabindex=\\"-1\\">Diners <a class=\\"header-anchor\\" href=\\"#diners\\" aria-label=\\"Permalink to &quot;Diners&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Diners 信用卡以 36、38 或者 30[0-5] 开头，长度为 14 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^3(?:0([0-5]|9)|[68]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d)</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{11}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>信用卡号的判断并不复杂，但是很多卡号有些特殊情况，需要注意。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://en.wikipedia.org/wiki/Payment_card_number\\" target=\\"_blank\\" rel=\\"noreferrer\\">Payment card number</a></p>\\n<p><a href=\\"https://www.regular-expressions.info/creditcard.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Finding or Verifying Credit Card Numbers</a></p>\\n"},{"title":"JavaScript中一个经典的正则例子","url":"/posts/2014-05-08-javascript-regular-expressions/","date":"2014-05-08 09:44","tags":["js","regex"],"html":"<p>学习知识的最好方法就是看例子.(个人观点) 因为书上总是会把概念和公式讲的晦涩难懂,才显得作者高大上.所以我总是喜欢\\n通过例子学习知识.每次写正则的时候总是喜欢查看例子学习如何使用,因为正则实在太耗脑细胞了,记不住,也没必要记住.学会\\n如何使用并在项目中熟练运用就好了,经常使用的话也就自然记住了.</p>\\n<p>JavaScript 语言精粹上面有个非常棒的学习例子,每次写正则的时候都会想起它.所以还是记一下分享给大家也方面我查询啦~</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> parse_url </span><span style=\\"color:#D73A49\\">=</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  /</span><span style=\\"color:#D73A49\\">^</span><span style=\\"color:#032F62\\">(?:(</span><span style=\\"color:#005CC5\\">[A-Za-z]</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\">):)</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\/</span><span style=\\"color:#D73A49\\">{0,3}</span><span style=\\"color:#032F62\\">)(</span><span style=\\"color:#005CC5\\">[0-9.\\\\-A-Za-z]</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\">)(?::(</span><span style=\\"color:#005CC5\\">\\\\d</span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(?:</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\/</span><span style=\\"color:#032F62\\">(</span><span style=\\"color:#005CC5\\">[</span><span style=\\"color:#D73A49\\">^</span><span style=\\"color:#005CC5\\">?#]</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(?:</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\?</span><span style=\\"color:#032F62\\">(</span><span style=\\"color:#005CC5\\">[</span><span style=\\"color:#D73A49\\">^</span><span style=\\"color:#005CC5\\">#]</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#032F62\\">(?:#(</span><span style=\\"color:#005CC5\\">.</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#032F62\\">))</span><span style=\\"color:#D73A49\\">?$</span><span style=\\"color:#032F62\\">/</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> url </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'http://www.ora.com:80/goodparts?q#fragment'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> result </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> parse_url.</span><span style=\\"color:#6F42C1\\">exec</span><span style=\\"color:#24292E\\">(url);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> names </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#032F62\\">'url'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'scheme'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'slash'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'host'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'port'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'path'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'query'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'hash'</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> blanks </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> '     '</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">var</span><span style=\\"color:#24292E\\"> i;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">for</span><span style=\\"color:#24292E\\"> (i </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">&#x3C;</span><span style=\\"color:#24292E\\"> names.</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">; i </span><span style=\\"color:#D73A49\\">+=</span><span style=\\"color:#005CC5\\"> 1</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(names[i] </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\"> ':'</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> blanks.</span><span style=\\"color:#6F42C1\\">substring</span><span style=\\"color:#24292E\\">(names[i].</span><span style=\\"color:#005CC5\\">length</span><span style=\\"color:#24292E\\">), result[i]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br></div></div><p>让我们分解 parse_url 的各个部分,看看它是如何工作的:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>^</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p><code>^</code>字符表示此字符串的开始.它是一个锚,指引 exec 不要跳过那些不像 URL(non-URL-like)的前缀,只匹配那些从开头就像 URL 一样的字符串:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:([A-Za-z]+):)?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这个因子匹配一个协议名,但仅当它后面跟随一个:(冒号)的时候才匹配.(?:...)表示一个非捕获型分组(noncapturing group).\\n后缀 ? 表示这个分组是可选的. 问号表示重复 0 次或一次.(...)表示一个捕获型分组(capturing group).一个捕获型分组会复制它\\n所匹配的文本,并把其放到 result 数组里.每个捕获型分组都会被指定一个编号.第一个捕获型分组的编号是 1,所以该分组所匹配的文本副本\\n会出现在 result[1]中.[...]表示一个字符类,A-Za-z 这个字符类包含 26 个大写字母和 26 个小写字母.连字符( - )表示范围从 A 到 Z.\\n后缀 + 表示这个字符类会被匹配一次或者多次.这个组后面跟着字符:,它会按字面进行匹配:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(\\\\/{0,3})</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>下一个因子是捕获型分组 2./表示该匹配/(斜扛).它是\\\\(反斜杠)来进行转义,这样它就不会被错误地解释为这个正则表达式的结束符.后缀{0,3}表示\\n/ 会被匹配 0 次,或者 1~3 次:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>([0-9.\\\\-A-Za-z]+)</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>下一个因子是捕获型分组 3.它会匹配一个主机名,由一个或多个数字、字母,以及 . 或 - 字符组成. - 会被转义为 \\\\- 以防止与表示范围的连字符想混淆:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?::(\\\\d+))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>下一个可选的因子匹配端口号,它是由一个前置 : 加上一个或多个数字而组成的序列. \\\\d 表示一个数字字符.一个或多个数字组成的数字串会被捕获型\\n分组 4 捕获:</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:\\\\/([^?#]*))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>接下来是另一个可选的分组.该分组以一个 / 开始. 之后的字符类[^?#]以一个 ^ 开始, 它表示这个类包含除了?和#之外的所有字符.*表示这个字符类\\n会被匹配 0 次或多次.</p>\\n<p>注意这里的处理是不严谨的.这个类匹配除?和#之外的所有字符,其中包括了行结束符、控制字符,以及其他大量不应在此被匹配的字符.大多数情况下,它会按照\\n我们的预期去做,但某些恶意文本可能会有渗透进来的风险.不严谨的正则表达式是一个常见的安全漏洞发源地.写不严谨的正则表达式比写严谨的正则表达式要容易得多.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:\\\\?([^#]*))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>接下来,还有一个以一个 ? 开始的可选分组.它包含捕获型分组 6,这个分组包含 0 个或多个非#字符.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>(?:#(.*))?</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>最后一个可选分组是以 # 开始的 .会匹配除行结束符以外的所有字符.</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>$</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>$表示这个字符串的结束.它保证在这个 URL 的尾部没有其他更多内容了.</p>\\n"}]},"relativePath":"tags/regex/index.md","filePath":"tags/[slug].md"}`),e={name:"tags/regex/index.md"};function p(l,o,r,t,c,i){return a(),n("div")}const u=s(e,[["render",p]]);export{y as __pageData,u as default};
